import React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'accent';
  size?: 'sm' | 'md' | 'lg' | 'icon';
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = 'primary', size = 'md', ...props }, ref) => {
    const variants = {
      primary: 'bg-[#003366] text-white hover:bg-[#002244]',
      secondary: 'bg-slate-200 text-slate-900 hover:bg-slate-300',
      outline: 'border-2 border-[#003366] text-[#003366] hover:bg-slate-100',
      ghost: 'hover:bg-slate-100 text-slate-700',
      accent: 'bg-[#FFD700] text-[#003366] font-bold hover:bg-[#e6c200] shadow-lg hover:shadow-xl'
    };

    const sizes = {
      sm: 'px-3 py-1.5 text-sm',
      md: 'px-6 py-2.5',
      lg: 'px-8 py-4 text-lg',
      icon: 'p-2'
    };

    return (
      <button
        ref={ref}
        className={cn(
          'inline-flex items-center justify-center rounded-lg transition-all duration-200 active:scale-95 disabled:opacity-50',
          variants[variant],
          sizes[size],
          className
        )}
        {...props}
      />
    );
  }
);

import React, { useState, useEffect, useRef } from 'react';
import { motion, useScroll, useTransform, useSpring } from 'framer-motion';

interface InfiniteGridProps {
  className?: string;
  children?: React.ReactNode;
}

export const InfiniteGrid: React.FC<InfiniteGridProps> = ({ className, children }) => {
  const [density, setDensity] = useState(40);
  const containerRef = useRef<HTMLDivElement>(null);
  const { scrollY } = useScroll();

  const yTranslate = useTransform(scrollY, [0, 1000], [0, -100]);
  const smoothY = useSpring(yTranslate, { damping: 20, stiffness: 100 });

  return (
    <div 
      ref={containerRef}
      className={`relative w-full overflow-hidden bg-slate-950 ${className}`}
      style={{ minHeight: '100vh' }}
    >
      {/* The Animated Grid */}
      <motion.div 
        className="absolute inset-0 pointer-events-none opacity-20"
        style={{ 
          backgroundImage: `linear-gradient(to right, #ffffff 1px, transparent 1px), linear-gradient(to bottom, #ffffff 1px, transparent 1px)`,
          backgroundSize: `${density}px ${density}px`,
          y: smoothY
        }}
        animate={{
            backgroundPosition: ["0px 0px", `${density}px ${density}px`]
        }}
        transition={{
            duration: 10,
            repeat: Infinity,
            ease: "linear"
        }}
      />

      {/* Radiant Gradient Overlay */}
      <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,transparent_0%,rgba(2,6,23,0.8)_80%)]" />

      {/* Content Area */}
      <div className="relative z-10 w-full">
        {children}
      </div>

      {/* Controls - Disappear on Mobile or Small screens if needed */}
      <div className="absolute bottom-4 right-4 z-20 hidden md:block bg-slate-900/50 backdrop-blur-sm border border-slate-800 p-3 rounded-xl text-white text-xs">
        <label className="block mb-1">Densidad de Red</label>
        <input 
          type="range" 
          min="20" 
          max="100" 
          value={density} 
          onChange={(e) => setDensity(Number(e.target.value))}
          className="w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-sst-yellow"
        />
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Menu, X, ChevronRight } from 'lucide-react';
import { Button } from '../ui/button';
import { WHATSAPP_URL } from '../../constants';

export const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { name: 'Servicios', href: '#servicios' },
    { name: 'Sectores', href: '#sectores' },
    { name: 'Proceso', href: '#proceso' },
    { name: 'Precio', href: '#precio' },
    { name: 'FAQ', href: '#faq' },
  ];

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? 'bg-white shadow-md py-2' : 'bg-transparent py-4'}`}>
      <div className="container mx-auto px-4 flex items-center justify-between">
        {/* Logo Variants */}
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 bg-[#003366] rounded-lg flex items-center justify-center text-white font-black text-xl">
            A&A
          </div>
          <div className={`hidden md:block text-xl font-bold ${isScrolled ? 'text-[#003366]' : 'text-white'}`}>
            Consultoras SST
          </div>
        </div>

        {/* Desktop Nav */}
        <nav className="hidden lg:flex items-center gap-8">
          {navItems.map((item) => (
            <a 
              key={item.name} 
              href={item.href} 
              className={`text-sm font-medium transition-colors ${isScrolled ? 'text-slate-600 hover:text-[#003366]' : 'text-white/80 hover:text-white'}`}
            >
              {item.name}
            </a>
          ))}
          <Button variant="accent" size="sm" onClick={() => window.open(WHATSAPP_URL, '_blank')}>
            Cotizar por WhatsApp
          </Button>
        </nav>

        {/* Mobile Toggle */}
        <button 
          className="lg:hidden p-2 text-slate-800" 
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X className={isScrolled ? 'text-slate-800' : 'text-white'} /> : <Menu className={isScrolled ? 'text-slate-800' : 'text-white'} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="lg:hidden absolute top-full left-0 right-0 bg-white shadow-xl animate-in fade-in slide-in-from-top-4">
          <div className="flex flex-col p-4 gap-4">
            {navItems.map((item) => (
              <a 
                key={item.name} 
                href={item.href} 
                className="text-lg font-medium text-slate-700 py-2 border-b border-slate-100 flex items-center justify-between"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                {item.name}
                <ChevronRight size={16} />
              </a>
            ))}
            <Button variant="accent" className="w-full py-4 mt-2" onClick={() => window.open(WHATSAPP_URL, '_blank')}>
              Cotizar por WhatsApp
            </Button>
          </div>
        </div>
      )}
    </header>
  );
};

